/**
 * Writes supabase/seed.sql from the built-in mock catalog.
 * Run: npx tsx scripts/generate-seed.ts
 */
import { writeFileSync } from "node:fs";
import { CATEGORIES } from "../lib/data/categories";
import { PRODUCTS } from "../lib/data/products";
import { ALL_RETAILERS, RETAILERS } from "../lib/data/retailers";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const arr = (a: string[]) => (a.length ? `array[${a.map(q).join(", ")}]::text[]` : "'{}'::text[]");
const bool = (b?: boolean) => (b ? "true" : "false");

const lines: string[] = [
  "-- Generated by scripts/generate-seed.ts from lib/data. Safe to re-run: existing rows are updated.",
  "",
  "insert into public.categories (id, name, emoji, tint, sort) values",
  CATEGORIES.map((c, i) => `  (${q(c.id)}, ${q(c.name)}, ${q(c.emoji)}, ${q(c.tint)}, ${i})`).join(",\n"),
  "on conflict (id) do update set name = excluded.name, emoji = excluded.emoji, tint = excluded.tint, sort = excluded.sort;",
  "",
  "insert into public.retailers (id, name, short, color, text_color, homepage, sort) values",
  ALL_RETAILERS.map((id, i) => {
    const r = RETAILERS[id];
    return `  (${q(r.id)}, ${q(r.name)}, ${q(r.short)}, ${q(r.color)}, ${q(r.text)}, ${q(r.homepage)}, ${i})`;
  }).join(",\n"),
  "on conflict (id) do update set name = excluded.name, short = excluded.short, color = excluded.color, text_color = excluded.text_color, homepage = excluded.homepage, sort = excluded.sort;",
  "",
  // Image ids, descriptions, highlights and store links are expanded in SQL to keep this file small.
  "insert into public.products (id, slug, name, brand, category_id, subcategory, emoji, image, tags, vibes, rating, review_count, is_new, trending, sort) values",
  PRODUCTS.map(
    (p, i) =>
      `(${q(p.id)},${q(p.slug)},${q(p.name)},${q(p.brand)},${q(p.category)},${q(p.subcategory)},${q(p.emoji)},${q(p.image.match(/photo-([^?]+)/)![1])},${arr(p.tags)},${arr(p.vibes)},${p.rating},${p.reviewCount},${bool(p.isNew)},${bool(p.trending)},${i})`,
  ).join(",\n"),
  "on conflict (id) do update set slug = excluded.slug, name = excluded.name, brand = excluded.brand, category_id = excluded.category_id, subcategory = excluded.subcategory, emoji = excluded.emoji, image = excluded.image, tags = excluded.tags, vibes = excluded.vibes, rating = excluded.rating, review_count = excluded.review_count, is_new = excluded.is_new, trending = excluded.trending, sort = excluded.sort;",
  "",
  "update public.products set",
  "  image = 'https://images.unsplash.com/photo-' || image || '?auto=format&fit=crop&w=800&q=70',",
  "  description = name || ' by ' || brand || ' — a fan-favourite in ' || lower(subcategory) || ' loved for being ' || array_to_string(tags[1:2], ' and ') || '. Compare live offers across retailers and grab it at the best price.',",
  "  highlights = array['Official ' || brand || ' product', 'Great for ' || tags[1], 'Price tracked daily across retailers', 'Free returns on most stores']",
  "where image not like 'http%';",
  "",
  "insert into public.offers (product_id, retailer_id, price, original_price, shipping, in_stock, url)",
  "select v.product_id, v.retailer_id, v.price, v.original_price, v.shipping, v.in_stock, 'https://example.com/' || v.retailer_id || '/' || p.slug",
  "from (values",
  PRODUCTS.flatMap((p) => p.offers.map((o) => `(${q(p.id)},${q(o.retailer)},${o.price},${o.originalPrice},${o.shipping},${bool(o.inStock)})`)).join(",\n"),
  ") as v (product_id, retailer_id, price, original_price, shipping, in_stock)",
  "join public.products p on p.id = v.product_id",
  "on conflict (product_id, retailer_id) do update set price = excluded.price, original_price = excluded.original_price, shipping = excluded.shipping, in_stock = excluded.in_stock, url = excluded.url;",
  "",
  "-- 89 days of illustrative history per offer (today's row comes from the offers trigger).",
  "-- Smooth waves plus a little noise and the odd flash-sale dip, deterministic via setseed.",
  "select setseed(0.42);",
  "insert into public.price_history (product_id, retailer_id, day, price)",
  "select o.product_id, o.retailer_id, current_date - d,",
  "  greatest(1, round(o.price * (",
  "    1.06",
  "    + 0.08 * sin((d + h) / 9.0)",
  "    + 0.04 * sin((d * 3 + h) / 13.0)",
  "    + (random() - 0.5) * 0.04",
  "    - case when (d + h) % 37 = 0 then 0.15 else 0 end",
  "  ))::int)",
  "from public.offers o",
  "cross join lateral (select abs(hashtext(o.product_id || o.retailer_id)) % 50 as h) seed",
  "cross join generate_series(1, 89) as d",
  "on conflict (product_id, retailer_id, day) do nothing;",
  "",
];

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`seed.sql: ${CATEGORIES.length} categories, ${ALL_RETAILERS.length} retailers, ${PRODUCTS.length} products, ${PRODUCTS.reduce((n, p) => n + p.offers.length, 0)} offers`);
